public final class GroupCommand implements CommandExecutor,TabCompleter{private final GroupService groups;public GroupCommand(GroupService g){groups=g;}public boolean onCommand(CommandSender s,Command c,String l,String[]a){if(!s.hasPermission("desertjungle.group.admin")){s.sendMessage("No permission.");return true;}if(a.length==3&&a[0].equalsIgnoreCase("assign")){var p=Bukkit.getPlayer(a[1]);if(p==null){s.sendMessage("Player offline.");return true;}try{groups.assign(p,a[2]);s.sendMessage("Group assigned.");}catch(IllegalArgumentException e){s.sendMessage(e.getMessage());}return true;}s.sendMessage("/group assign <player> <group>");return true;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[]a){return a.length==1?List.of("assign"):List.of();}}
